changeSet.sql:
CREATE TABLE chat_participants ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, chat_id UUID NOT NULL, profile_id BIGINT NOT NULL, -- Nessuna FK verso profiles: integrità garantita a livello applicativo. role TEXT NOT NULL DEFAULT 'member' CHECK (role IN ('admin','member')), is_muted BOOLEAN NOT NULL DEFAULT FALSE, last_read_message_id UUID, joined_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), left_at TIMESTAMPTZ,
CONSTRAINT CHAT_PARTICIPANTS_CHAT_FK FOREIGN KEY (chat_id) REFERENCES chats(id) ON DELETE CASCADE, CONSTRAINT CHAT_PARTICIPANTS_LAST_READ_FK FOREIGN KEY (last_read_message_id) REFERENCES messages(id) ON DELETE SET NULL -- Le FK verso chats e messages sono interne a directs-service → rimangono. );
CREATE UNIQUE INDEX idx_cp_unique_active ON chat_participants(chat_id, profile_id) WHERE left_at IS NULL; CREATE INDEX idx_cp_chat ON chat_participants(chat_id) WHERE left_at IS NULL; CREATE INDEX idx_cp_profile ON chat_participants(profile_id) WHERE left_at IS NULL;
